+fn normalize(resp: &MatchExternalKvResponse) -> Vec<(String, i32, Vec<i64>)> {
+    let mut out: Vec<(String, i32, Vec<i64>)> = resp
+        .matches
+        .iter()
+        .flat_map(|node| {
+            node.hashes_by_tier.iter().map(|tier| {
+                let mut hashes = tier.hashes.clone();
