+// ---- a Valkey to test against -------------------------------------------------
+
+macro_rules! require_valkey {
+    () => {
+        match ValkeyServer::start() {
+            Some(server) => server,
+            None => {
+                eprintln!(
+                    "skipping: no valkey-server on PATH and KV_INDEXER_TEST_VALKEY_URL unset"
+                );
+                return;
+            }
+        }
+    };
+}
